        {"대지":"제목", "내용":"돌아오라 그리하면 - 회개의 초대", "예화_적용":"하나님은 우리가 돌아오기를 간절히 기다리신다"},
        {"대지":"서론", "내용":"진노의 선포(2절) 다음에 바로 은혜의 초대(3절)가 온다. '돌아오라.' 이 한마디에 하나님의 마음이 담겨 있다. 진노의 하나님이 동시에 초대의 하나님이시다. 그리고 놀라운 약속 — '너희가 돌아오면 나도 돌아가겠다'", "예화_적용":"탕자를 기다리는 아버지처럼 하나님은 우리를 기다리신다"},
        {"대지":"1대지: 너희는 내게로 돌아오라 (하나님의 초대)", "내용":"회개의 첫걸음은 하나님의 초대. 우리가 찾기 전에 하나님이 먼저 부르신다", "예화_적용":"하나님의 초대를 거부하지 말라. 지금이 돌아올 때이다"},
        {"대지":"2대지: 그리하면 내가 돌아가리라 (하나님의 약속)", "내용":"우리의 회개에 대한 하나님의 응답. 우리가 한 발 다가가면 하나님이 열 발 다가오신다", "예화_적용":"하나님은 우리의 작은 돌이킴에도 크게 응답하시는 분이다"},
        {"대지":"3대지: 만군의 여호와의 말이니라 (삼중 확인)", "내용":"세 번의 신탁 공식. 이 약속은 절대적으로 확실하다", "예화_적용":"하나님의 약속을 의심하지 말라. 삼중으로 확인하신 약속이다"},
        {"대지":"결론", "내용":"하나님은 지금도 '돌아오라'고 부르신다. 이 초대를 거절할 이유가 무엇인가. 돌아가면 하나님이 기다리고 계신다. 오늘 이 시간, 마음을 돌이켜 하나님께로 가자", "예화_적용":"지금 이 순간이 돌아올 수 있는 은혜의 때이다. 내일은 너무 늦을 수 있다"}
