        {"상황":"과거의 실수를 반복하는 분", "성경원리":"역사에서 배우지 못하면 같은 실수를 반복한다. 조상의 실패가 경고가 되어야 한다", "실제적용":"같은 실수의 패턴을 기록하고 구체적 대안을 세우라. 반복의 고리를 끊는 것은 가능하다"}
