        {"상황":"하나님의 인도를 기다리는 분", "성경원리":"스가랴는 첫 예언(8월)에서 환상(11월)까지 3개월을 기다렸다. 하나님의 때가 있다", "실제적용":"기다림의 시간도 하나님의 계획 안에 있다. 조급해하지 말고 기도하며 기다리라"},
        {"상황":"하나님의 말씀을 더 깊이 알고 싶은 분", "성경원리":"하나님의 계시는 점진적으로 깊어진다. 회개 촉구(1-6절)에서 환상 계시(7절~)로 진행", "실제적용":"기본적인 순종(회개)이 선행되면 더 깊은 계시가 주어진다. 아는 것부터 실천하라"}
