        {"구절":"계 19:11", "연결점":"흰 말을 탄 충신과 진실이라 칭하는 이", "구분":"신약"},
        {"구절":"히 1:14", "연결점":"봉사하는 영으로 구원받을 자들을 위하여 보냄", "구분":"신약"},
        {"구절":"계 2:1", "연결점":"일곱 교회 가운데 다니시는 그리스도", "구분":"신약"},
        {"구절":"빌 2:7-8", "연결점":"자기를 비워 종의 형체를 가지사 낮아지신 그리스도", "구분":"신약"}
