        {"상황":"기도 응답이 없어 지치는 분", "성경원리":"여호와의 사자도 '언제까지'라고 물으셨다. 오래 기다리는 것은 약속이 무효화된 것이 아니다", "실제적용":"기도를 포기하지 말라. '언제까지'라고 울부짖는 것 자체가 믿음의 기도이다"},
        {"상황":"혼자 고통받고 있다고 느끼는 분", "성경원리":"여호와의 사자가 이스라엘의 고통을 자기 것으로 여기고 중보하셨다. 그리스도도 우리를 위해 중보하신다", "실제적용":"당신은 혼자 고통받는 것이 아니다. 그리스도가 당신의 고통을 아시고 아버지께 중보하고 계신다"},
        {"상황":"하나님이 긍휼하시지 않는 것 같은 분", "성경원리":"하나님의 진노에도 기한이 있다(70년). '영원히'가 아니라 '잠깐'이다 (시 30:5)", "실제적용":"고통의 시간이 영원할 것 같지만, 하나님의 긍휼이 반드시 온다. 조금만 더 기다리라"}
