        {"원어":"צְבָאוֹת (체바오트)", "의미_문법":"만군 - 명사 복수. 군대의 주", "설교포인트":"만군의 주가 직접 백성을 위해 열심을 내신다"},
        {"원어":"קְרָא (케라)", "의미_문법":"외치다 - 동사 칼형. 선포하다", "설교포인트":"하나님의 메시지는 조용히 속삭이는 것이 아니라 외쳐 선포해야 한다"}
