        {"대지":"서론", "내용":"스가랴가 눈을 들어 보니 네 뿔이 보인다. 뿔은 힘과 권력의 상징이다. 이스라엘을 사방에서 공격한 열국의 힘이 뿔로 나타났다. 그러나 이 환상은 두려움이 아니라 소망의 메시지이다", "예화_적용":"암 진단이 두렵지만 치료 계획이 함께 주어지듯 하나님은 위험과 구원을 함께 보여주신다"},
        {"대지":"1대지: 눈을 들어 봄 (영적 시각의 개방)", "내용":"스가랴가 '눈을 들어' 봄은 하나님이 주시는 영적 시각을 받은 것. 자연적 눈으로는 볼 수 없는 영적 실재", "예화_적용":"엘리사의 종이 눈이 열려 불말과 불병거를 본 것처럼 영적 눈을 열어야 한다"},
        {"대지":"2대지: 네 뿔의 실체 (세상 권력의 위협)", "내용":"네 뿔은 사방에서 이스라엘을 공격한 열국의 군사력. 압도적으로 보이는 세상의 힘", "예화_적용":"소년 다윗 앞의 골리앗처럼 세상의 힘은 압도적으로 보이지만"},
        {"대지":"3대지: 뿔 뒤에 계신 하나님 (주권적 통치)", "내용":"네 뿔도 하나님의 주권 아래 있다. 이 환상을 보여주신 분이 하나님이심이 그 증거", "예화_적용":"체스판의 모든 말을 보는 것처럼 하나님은 전체 상황을 주관하신다"},
        {"대지":"결론", "내용":"세상의 권력이 아무리 강해 보여도 하나님의 주권 아래 있다. 눈을 들어 하나님이 보여주시는 것을 보라. 위험 뒤에 구원이 있다", "예화_적용":"뿔이 보일 때 두려워하지 말고 뿔을 보여주시는 하나님을 바라보라"}
