        {"새찬송가":"310", "통일찬송가":"194", "제목":"예수 이름으로", "선정이유":"모든 적의 권세를 이기시는 예수의 능력"},
        {"새찬송가":"389", "통일찬송가":"293", "제목":"행군 나팔 소리에", "선정이유":"영적 전쟁에서의 승리"}
