        {"영어원문":"Run and tell the young man that his measuring line is too short for what God designs Jerusalem to be.", "한국어번역":"달려가서 소년에게 그의 측량 줄이 하나님이 예루살렘에 계획하신 것에 비해 너무 짧다고 전하라.", "핵심통찰":"인간의 측량은 하나님의 계획에 비해 항상 부족하다"},
        {"영어원문":"The city shall extend far beyond its former limits, God's blessing making it too large for any wall.", "한국어번역":"이 도시는 이전의 한계를 훨씬 넘어 확장되리니 하나님의 축복이 어떤 성벽에도 담기지 않게 하실 것이다.", "핵심통찰":"하나님의 축복은 어떤 한계에도 담기지 않는다"}
