        {"항목":"영광을 위한 보내심", "내용":"열국 심판은 하나님의 영광을 드러내기 위한 것. 하나님의 모든 역사의 궁극적 목적은 영광", "목회적활용":"하나님의 모든 행동의 최종 목적은 그분의 영광"},
        {"항목":"노략한 열국", "내용":"이스라엘을 약탈한 바벨론 등 열국에 대한 심판 선언. 약탈자가 오히려 약탈당할 것", "목회적활용":"하나님의 백성을 핍박한 자는 반드시 대가를 치른다"}
