        {"대지":"결론", "내용":"우리 모두는 더러운 옷을 입은 여호수아이다. 그러나 절망할 필요 없다. 4절에서 하나님이 아름다운 옷으로 바꿔주실 것이기 때문이다. 핵심은 우리의 자격이 아닌 하나님의 은혜이다", "예화_적용":"더러운 옷이 끝이 아니라 새 옷으로의 시작점이다"}
