        {"원어":"הֶעֱבַרְתִּי (헤에바르티)", "의미_문법":"제하여 버렸다 - 동사 히필형. 지나가게 하다/제거하다", "설교포인트":"과거형 표현 - 이미 완료된 죄의 제거"},
        {"원어":"מַחֲלָצוֹת (마할라초트)", "의미_문법":"아름다운 옷/예복 - 명사 복수. 축제용 의복", "설교포인트":"더러운 옷 대신 아름다운 예복 - 의의 옷으로의 교체"}
