        {"대지":"2대지: 일곱 눈 (완전한 지혜와 감찰)", "내용":"일곱 눈은 완전한 수의 눈. 모든 것을 보시고 아시는 하나님의 완전한 지식", "예화_적용":"360도 카메라처럼 모든 것을 빠짐없이 보시는 하나님의 감찰"},
        {"대지":"3대지: 하루에 죄를 제함 (십자가의 완전한 속죄)", "내용":"매년 반복되는 대속죄일이 아닌 단 한 번의 완전한 속죄. 십자가의 그 하루", "예화_적용":"수천 번의 치료로 못 고친 병을 한 번의 수술로 완치하듯"},
        {"대지":"결론", "내용":"하나님이 세우신 돌, 그리스도를 보라. 일곱 눈으로 모든 것을 아시고 하루에 모든 죄를 제하셨다. 이보다 더 완전한 구원은 없다. 이 돌 위에 당신의 삶을 세우라", "예화_적용":"십자가의 그 하루가 인류 역사를 영원히 바꾸었다"}
