        {"원어":"יָדָיו (야다브)", "의미_문법":"그의 손 - 명사+접미사. 스룹바벨의 손", "설교포인트":"같은 손이 시작과 완성을 모두 함"},
        {"원어":"שְׁלָחָנִי (쉘라하니)", "의미_문법":"나를 보내셨다 - 동사+접미사. 파송", "설교포인트":"성전 완공이 하나님의 보내심의 증거"}
