        {"구절":"요 16:12-13", "연결점":"내가 아직도 너희에게 이를 것이 많으나 진리의 성령이 오시면", "구분":"신약"},
        {"구절":"엡 3:18-19", "연결점":"그 넓이와 길이와 높이와 깊이가 어떠함을 깨달아", "구분":"신약"},
        {"구절":"고전 13:12", "연결점":"지금은 거울로 보는 것 같이 희미하나 그 때에는 얼굴과 얼굴을 대하여", "구분":"신약"}
