        {"교리":"풍성한 공급", "설명":"기름이 '흘려내림(쏟아짐)'은 성령의 공급이 인색하지 않고 풍성함을 보여줌", "관련구절":"욜 2:28, 행 2:17, 딛 3:6, 엡 5:18"},
        {"교리":"귀중한 기름", "설명":"'금빛 기름'이라는 표현은 성령의 기름이 가장 귀한 것임을 보여줌", "관련구절":"시 133:2, 행 10:38, 눅 4:18, 삼상 16:13"}
